starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "queue_name" {
  description = "Input variable queue_name."
  type        = string
  default     = "jobs"
}

variable "dlq_name" {
  description = "Input variable dlq_name."
  type        = string
  default     = "jobs-dlq"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_sqs_queue" "this" {
  # TODO - Complete the main queue.
  # Add the queue name, server-side encryption and redrive policy pointing at the DLQ.
}

resource "aws_sqs_queue" "dlq" {
  name = var.dlq_name
}
